<?php
/**
 * hcwa-2026 page patterns (docs/plan/11-WP-PORT.md 4.4): static checks that need no WordPress.
 *
 * The ten patterns are generated by scripts/build-wp-patterns.py from content/draft/*.json.
 * Checked here: headers as WP_Theme::get_block_patterns() reads them, VI/EN pairs with the
 * same blocks, one locked hcwa/sections block holding only hcwa/* blocks, attributes that
 * exist in each block.json with the right types and allowed values, one H1 block per page,
 * and the safety rules (no image, no markup, no data-draft; draft text stored whole as
 * [DRAFT: …] so it never prints on production).
 *
 * @package hcwa-2026
 */

$hcwa_root          = dirname( __DIR__, 2 );
$hcwa_pattern_dir   = dirname( __DIR__ ) . '/themes/hcwa-2026/patterns';
$hcwa_blocks_dir    = dirname( __DIR__ ) . '/plugins/hcwa-core/blocks';
$hcwa_pattern_files = glob( $hcwa_pattern_dir . '/*.php' );
sort( $hcwa_pattern_files );

$hcwa_pages = array( 'page-home', 'page-our-work', 'page-get-involved', 'page-donate', 'page-contact' );
$hcwa_want  = array();
foreach ( $hcwa_pages as $hcwa_page ) {
	$hcwa_want[] = "$hcwa_page-en.php";
	$hcwa_want[] = "$hcwa_page-vi.php";
}
sort( $hcwa_want );
hcwa_assert_same( $hcwa_want, array_map( 'basename', $hcwa_pattern_files ), 'exactly the ten page patterns (4.4)' );

// The generator is current (the static check also runs it).
$hcwa_python = trim( (string) shell_exec( 'command -v python3 2>/dev/null' ) );
if ( '' === $hcwa_python ) {
	hcwa_test_skip( 'patterns are current: python3 is not installed' );
} else {
	exec( escapeshellarg( $hcwa_python ) . ' -I ' . escapeshellarg( $hcwa_root . '/scripts/build-wp-patterns.py' ) . ' --check 2>&1', $hcwa_out, $hcwa_code );
	hcwa_assert_same( 0, $hcwa_code, 'patterns are current with content/draft (python3 scripts/build-wp-patterns.py): ' . implode( ' ', (array) $hcwa_out ) );
}

// Block attributes from each block.json.
$hcwa_meta = array();
foreach ( glob( $hcwa_blocks_dir . '/*/block.json' ) as $hcwa_file ) {
	$hcwa_json                       = json_decode( (string) file_get_contents( $hcwa_file ), true );
	$hcwa_meta[ $hcwa_json['name'] ] = (array) ( $hcwa_json['attributes'] ?? array() );
}
$hcwa_type_ok = static function ( $value, array $spec ): bool {
	switch ( $spec['type'] ?? '' ) {
		case 'string':
			return is_string( $value ) && ( empty( $spec['enum'] ) || in_array( $value, $spec['enum'], true ) );
		case 'array':
			if ( ! is_array( $value ) || ! array_is_list( $value ) ) {
				return false;
			}
			$enum = $spec['items']['enum'] ?? null;
			return null === $enum || ! array_diff( $value, $enum );
		case 'boolean':
			return is_bool( $value );
		case 'integer':
			return is_int( $value );
	}
	return false;
};
// Every string inside an attribute value, with its path.
$hcwa_strings = static function ( $value, string $path ) use ( &$hcwa_strings ): array {
	if ( is_string( $value ) ) {
		return array( $path => $value );
	}
	if ( ! is_array( $value ) ) {
		return array();
	}
	$out = array();
	foreach ( $value as $k => $v ) {
		$out += $hcwa_strings( $v, "$path.$k" );
	}
	return $out;
};
$hcwa_shape = static function ( array $blocks ) use ( &$hcwa_shape ): array {
	$out = array();
	foreach ( $blocks as $b ) {
		if ( null === $b['blockName'] ) {
			continue;
		}
		$out[] = array( $b['blockName'], array_keys( $b['attrs'] ), $hcwa_shape( $b['innerBlocks'] ) );
	}
	return $out;
};

$hcwa_shapes = array();
foreach ( $hcwa_pattern_files as $hcwa_file ) {
	$hcwa_base = basename( $hcwa_file, '.php' );
	$hcwa_src  = (string) file_get_contents( $hcwa_file );
	$hcwa_lang = substr( $hcwa_base, -2 );
	$hcwa_page = substr( $hcwa_base, 0, -3 );

	// Headers (WP_Theme::get_block_patterns()).
	hcwa_assert_same( 1, preg_match( '/^ \* Title: .+\((Tiếng Việt|English)\)$/mu', $hcwa_src ), "$hcwa_base: Title names the language" );
	hcwa_assert_contains( " * Slug: hcwa-2026/$hcwa_base\n", $hcwa_src, "$hcwa_base: slug" );
	hcwa_assert_contains( " * Categories: hcwa\n", $hcwa_src, "$hcwa_base: category" );
	hcwa_assert_contains( " * Post Types: page\n", $hcwa_src, "$hcwa_base: offered for pages" );
	hcwa_assert_contains( " * Block Types: core/post-content\n", $hcwa_src, "$hcwa_base: offered for a new page" );
	hcwa_assert_same( 1, preg_match( '/^ \* Description: \S.+$/mu', $hcwa_src ), "$hcwa_base: description" );
	hcwa_assert_contains( "defined( 'ABSPATH' ) || exit;", $hcwa_src, "$hcwa_base: direct-access guard" );
	hcwa_assert_contains( 'GENERATED by scripts/build-wp-patterns.py', $hcwa_src, "$hcwa_base: marked as generated" );

	$hcwa_body = substr( $hcwa_src, (int) strpos( $hcwa_src, '?>' ) + 2 );
	hcwa_assert_same( substr_count( $hcwa_body, '<!-- wp:' ) - substr_count( $hcwa_body, '/-->' ), substr_count( $hcwa_body, '<!-- /wp:' ), "$hcwa_base: block comments balance" );
	hcwa_assert_false( (bool) preg_match( '/<(?!!--)[a-z]/i', $hcwa_body ), "$hcwa_base: no literal HTML, only block comments" );
	hcwa_assert_false( str_contains( $hcwa_body, 'data-draft' ), "$hcwa_base: no data-draft (the render adds it)" );
	hcwa_assert_false( (bool) preg_match( '/\.(jpe?g|png|webp|avif|gif)\b|wp-content\/uploads/i', $hcwa_body ), "$hcwa_base: no image" );

	$hcwa_blocks = array_values( array_filter( parse_blocks( $hcwa_body ), static fn( $b ) => null !== $b['blockName'] ) );
	hcwa_assert_same( 1, count( $hcwa_blocks ), "$hcwa_base: one top-level block" );
	$hcwa_sections = $hcwa_blocks[0] ?? array( 'blockName' => null, 'attrs' => array(), 'innerBlocks' => array() );
	hcwa_assert_same( 'hcwa/sections', $hcwa_sections['blockName'], "$hcwa_base: the page is one hcwa/sections block" );
	hcwa_assert_true( in_array( $hcwa_sections['attrs']['templateLock'] ?? '', array( 'contentOnly', 'all' ), true ), "$hcwa_base: sections are locked (4.2)" );
	hcwa_assert_same( array( 'move' => true, 'remove' => true ), $hcwa_sections['attrs']['lock'] ?? null, "$hcwa_base: hcwa/sections cannot be moved or removed" );

	// Every block inside: one of ours, contract attributes only, text stored safely.
	$hcwa_h1    = 0;
	$hcwa_stack = $hcwa_sections['innerBlocks'];
	$hcwa_names = array();
	while ( $hcwa_stack ) {
		$hcwa_block = array_shift( $hcwa_stack );
		$hcwa_name  = (string) $hcwa_block['blockName'];
		if ( '' === $hcwa_name ) {
			hcwa_assert_same( '', trim( (string) $hcwa_block['innerHTML'] ), "$hcwa_base: nothing between sections" );
			continue;
		}
		$hcwa_names[] = $hcwa_name;
		hcwa_assert_true( isset( $hcwa_meta[ $hcwa_name ] ), "$hcwa_base: $hcwa_name is an hcwa-core block" );
		if ( in_array( $hcwa_name, array( 'hcwa/hero', 'hcwa/lit-header', 'hcwa/involve-head', 'hcwa/sun-head' ), true ) ) {
			++$hcwa_h1;
		}
		if ( 'hcwa/day' === $hcwa_name ) {
			hcwa_assert_same( $hcwa_sections['attrs']['templateLock'] ?? null, $hcwa_block['attrs']['templateLock'] ?? null, "$hcwa_base: hcwa/day is locked like its container" );
		}
		foreach ( $hcwa_block['attrs'] as $hcwa_attr => $hcwa_value ) {
			$hcwa_spec = $hcwa_meta[ $hcwa_name ][ $hcwa_attr ] ?? null;
			hcwa_assert_true( null !== $hcwa_spec || 'lock' === $hcwa_attr, "$hcwa_base: $hcwa_name.$hcwa_attr is a block attribute" );
			if ( null !== $hcwa_spec ) {
				hcwa_assert_true( $hcwa_type_ok( $hcwa_value, $hcwa_spec ), "$hcwa_base: $hcwa_name.$hcwa_attr has the block.json type and an allowed value" );
			}
			foreach ( $hcwa_strings( $hcwa_value, "$hcwa_name.$hcwa_attr" ) as $hcwa_path => $hcwa_text ) {
				hcwa_assert_same( $hcwa_text, hcwa_attr_text( $hcwa_text ), "$hcwa_base: $hcwa_path is plain text" );
				if ( str_contains( $hcwa_text, '[' ) && hcwa_text_has_draft( $hcwa_text ) && str_starts_with( $hcwa_text, '[DRAFT' ) ) {
					hcwa_assert_same( 1, preg_match( '/^\[DRAFT: .*\]$/su', $hcwa_text ), "$hcwa_base: $hcwa_path draft is stored whole" );
					hcwa_assert_same( '', hcwa_draft_text( $hcwa_text, true )['text'], "$hcwa_base: $hcwa_path prints nothing on production" );
				}
			}
		}
		foreach ( $hcwa_block['innerBlocks'] as $hcwa_inner ) {
			$hcwa_stack[] = $hcwa_inner;
		}
	}
	hcwa_assert_same( 1, $hcwa_h1, "$hcwa_base: one block carries the page's H1" );
	hcwa_assert_true( count( $hcwa_names ) >= 3, "$hcwa_base: the page's sections are there" );
	$hcwa_shapes[ $hcwa_page ][ $hcwa_lang ] = $hcwa_shape( $hcwa_blocks );
}

// VI and EN of a page hold the same blocks with the same attributes.
foreach ( $hcwa_pages as $hcwa_page ) {
	hcwa_assert_same( $hcwa_shapes[ $hcwa_page ]['vi'] ?? null, $hcwa_shapes[ $hcwa_page ]['en'] ?? null, "$hcwa_page: VI and EN have the same blocks and attributes" );
}

// The page order of the home pattern is the prototype's (H2 to H10).
$hcwa_home = array_column( $hcwa_shapes['page-home']['vi'][0][2] ?? array(), 0 );
hcwa_assert_same( array( 'hcwa/hero', 'hcwa/passage', 'hcwa/corridor', 'hcwa/work-sheet', 'hcwa/news-latest', 'hcwa/shutters', 'hcwa/help', 'hcwa/partner-wall', 'hcwa/dusk-band' ), $hcwa_home, 'home: the prototype\'s section order' );

// The old patterns are gone (4.4: replaced by the page patterns).
foreach ( array( 'hero-split', 'focus-areas', 'cta-band', 'ways-to-help', 'faq', 'contact-band', 'page-header' ) as $hcwa_old ) {
	hcwa_assert_false( is_file( "$hcwa_pattern_dir/$hcwa_old-vi.php" ) || is_file( "$hcwa_pattern_dir/$hcwa_old-en.php" ), "old pattern $hcwa_old is deleted" );
}
